-- Additive only: no existing Subproject or financial records are rewritten.
begin;
set local lock_timeout='5s';
lock table public.subprojects,public.financial_obligations,public.financial_disbursements,public.subproject_accomplishments,public.budget_item_adjustment_history in share mode;
do $$
declare fingerprints jsonb;
begin
  select jsonb_object_agg(table_name,signature) into fingerprints from (
    select 'subprojects' as table_name,jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) as signature from public.subprojects r
    union all select 'financial_obligations',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.financial_obligations r
    union all select 'financial_disbursements',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.financial_disbursements r
    union all select 'subproject_accomplishments',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.subproject_accomplishments r
    union all select 'budget_item_adjustment_history',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.budget_item_adjustment_history r
  ) signatures;
  perform set_config('app.subproject_actuals_install_fingerprints',fingerprints::text,true);
end; $$;
create table if not exists public.subproject_financial_entry_state (
  subproject_id bigint not null references public.subprojects(id) on delete cascade,
  item_id text not null,
  stage text not null check(stage in ('obligation','disbursement')),
  primary key(subproject_id,item_id,stage)
);
create table if not exists public.subproject_accomplishment_requests (
  request_key uuid primary key, subproject_id bigint not null references public.subprojects(id),
  actor_id bigint not null references public.users(id), request_hash text not null,
  response jsonb not null, created_at timestamptz not null default now()
);
create table if not exists public.subproject_accomplishment_revisions (
  id bigint generated by default as identity primary key,
  subproject_id bigint not null references public.subprojects(id), actor_id bigint references public.users(id),
  request_key uuid not null, reason text, changes jsonb not null,
  created_at timestamptz not null default now()
);
alter table public.subproject_financial_entry_state enable row level security;
alter table public.subproject_accomplishment_requests enable row level security;
alter table public.subproject_accomplishment_revisions enable row level security;
revoke all on public.subproject_financial_entry_state,public.subproject_accomplishment_requests,public.subproject_accomplishment_revisions from anon,authenticated;
grant all on public.subproject_financial_entry_state,public.subproject_accomplishment_requests,public.subproject_accomplishment_revisions to service_role;

-- Records that have used the central ledger must never fall back to stale JSON
-- after the last explicit deletion. The trigger also serializes old/new writers.
create or replace function public.track_subproject_financial_entry_state() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare stage_value text;
begin
  stage_value:=case when tg_table_name='financial_obligations' then 'obligation' else 'disbursement' end;
  if tg_op in ('UPDATE','DELETE') and old.entity_type='subproject_detail' then
    perform id from public.subprojects where id=old.parent_id for update;
    if found and old.item_id is not null then
      insert into public.subproject_financial_entry_state values(old.parent_id,old.item_id::text,stage_value) on conflict do nothing;
    end if;
  end if;
  if tg_op in ('INSERT','UPDATE') and new.entity_type='subproject_detail' then
    perform id from public.subprojects where id=new.parent_id for update;
    if found and new.item_id is not null then
      insert into public.subproject_financial_entry_state values(new.parent_id,new.item_id::text,stage_value) on conflict do nothing;
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end; $$;
drop trigger if exists track_subproject_financial_entry_state on public.financial_obligations;
create trigger track_subproject_financial_entry_state before insert or update or delete on public.financial_obligations for each row execute function public.track_subproject_financial_entry_state();
drop trigger if exists track_subproject_financial_entry_state on public.financial_disbursements;
create trigger track_subproject_financial_entry_state before insert or update or delete on public.financial_disbursements for each row execute function public.track_subproject_financial_entry_state();

create or replace function public.subproject_accomplishment_actor(p_actor_id bigint,p_password text,p_subproject_id bigint,p_surface text)
returns public.users language plpgsql security definer set search_path=public,pg_temp as $$
declare a public.users%rowtype; r public.roles_config%rowtype; parent public.subprojects%rowtype; module_name text; scope_value text; v jsonb;
begin
  if p_surface is null or p_surface not in ('subproject','financial','physical') then raise exception 'Invalid accomplishment entry surface.'; end if;
  select * into a from public.users where id=p_actor_id;
  if a.id is null or a.role is null then raise exception 'Your session could not be verified.' using errcode='42501'; end if;
  if auth.uid() is not null then
    if a.auth_id is distinct from auth.uid() then raise exception 'Your session does not match this request.' using errcode='42501'; end if;
  elsif nullif(p_password,'') is null or a.password is distinct from p_password then
    raise exception 'Your session could not be verified.' using errcode='42501';
  end if;
  module_name:=case when p_surface='subproject' then 'Subprojects' when p_surface='physical' then 'Accomplishment - Physical' else 'Accomplishment - Financial' end;
  select * into r from public.roles_config where role=a.role and module=module_name limit 1;
  v:=a.permissions_override->module_name->'can_view';
  if a.role not in ('Super Admin','Administrator') and not(case when jsonb_typeof(v)='boolean' then (v#>>'{}')::boolean else coalesce(r.can_view,true) end) then
    raise exception 'You do not have permission to view these accomplishments.' using errcode='42501';
  end if;
  select * into parent from public.subprojects where id=p_subproject_id;
  if parent.id is null then raise exception 'The Subproject is no longer available.' using errcode='P0002'; end if;
  scope_value:=case when a.visibility_scope in ('Own OU','All OUs') then a.visibility_scope
    when r.visibility_scope in ('Own OU','All OUs') then r.visibility_scope
    when a.role in ('Super Admin','Administrator','Management') then 'All OUs' else 'Own OU' end;
  if scope_value='Own OU' and parent."operatingUnit" is distinct from a."operatingUnit" then raise exception 'The Subproject is outside your OU scope.' using errcode='42501'; end if;
  return a;
end; $$;

create or replace function public.subproject_financial_stage(p_parent jsonb,p_item_id text,p_stage text)
returns jsonb language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare result jsonb; line jsonb; arr jsonb; array_key text; amount_key text; date_key text;
begin
  if p_stage not in ('obligation','disbursement') then raise exception 'Invalid financial stage.'; end if;
  if p_stage='obligation' then
    select jsonb_agg(jsonb_build_object('id',id::text,'date',obligation_date::text,'amount',amount,'remarks',coalesce(remarks,'')) order by id) into result
      from public.financial_obligations where entity_type='subproject_detail' and parent_id=(p_parent->>'id')::bigint and item_id::text=p_item_id;
  else
    select jsonb_agg(jsonb_build_object('id',id::text,'date',disbursement_date::text,'amount',amount,'remarks',coalesce(remarks,'')) order by id) into result
      from public.financial_disbursements where entity_type='subproject_detail' and parent_id=(p_parent->>'id')::bigint and item_id::text=p_item_id;
  end if;
  if result is not null or exists(select 1 from public.subproject_financial_entry_state where subproject_id=(p_parent->>'id')::bigint and item_id=p_item_id and stage=p_stage) then
    return jsonb_build_object('source','central','entries',coalesce(result,'[]'::jsonb));
  end if;
  select value into line from jsonb_array_elements(coalesce(nullif(p_parent->'details','null'::jsonb),'[]'::jsonb)) where value->>'id'=p_item_id;
  array_key:=case when p_stage='obligation' then 'obligations' else 'disbursements' end;
  amount_key:=case when p_stage='obligation' then 'actualObligationAmount' else 'actualDisbursementAmount' end;
  date_key:=case when p_stage='obligation' then 'actualObligationDate' else 'actualDisbursementDate' end;
  arr:=coalesce(nullif(line->array_key,'null'::jsonb),'[]'::jsonb);
  if jsonb_array_length(arr)=0 and coalesce((line->>amount_key)::numeric,0)<>0 then
    arr:=jsonb_build_array(jsonb_build_object('date',coalesce(line->>date_key,''),'amount',(line->>amount_key)::numeric,'remarks','Legacy Record'));
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id','legacy:'||p_stage||':'||p_item_id||':'||(ordinality-1)::text,
    'date',coalesce(value->>'date',''),'amount',coalesce((value->>'amount')::numeric,0),'remarks',coalesce(value->>'remarks','')) order by ordinality),'[]'::jsonb)
    into result from jsonb_array_elements(arr) with ordinality;
  return jsonb_build_object('source','legacy','entries',result);
end; $$;

create or replace function public.subproject_accomplishment_snapshot(p_parent jsonb) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare stages jsonb:='{}'; line jsonb; item_id text;
begin
  if exists(select 1 from jsonb_array_elements(coalesce(nullif(p_parent->'details','null'::jsonb),'[]'::jsonb)) e group by e->>'id' having e->>'id' is null or count(*)>1) then raise exception 'Budget item identities are ambiguous. No changes were saved.'; end if;
  for line in select value from jsonb_array_elements(coalesce(nullif(p_parent->'details','null'::jsonb),'[]'::jsonb)) loop
    item_id:=line->>'id';
    stages:=stages||jsonb_build_object(item_id,jsonb_build_object('obligation',public.subproject_financial_stage(p_parent,item_id,'obligation'),'disbursement',public.subproject_financial_stage(p_parent,item_id,'disbursement')));
  end loop;
  return jsonb_build_object('subproject',p_parent,'stages',stages);
end; $$;

create or replace function public.read_subproject_accomplishments(p_actor_id bigint,p_actor_password text,p_subproject_ids bigint[],p_surface text)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare parent public.subprojects%rowtype; result jsonb:='[]'; id_value bigint;
begin
  if coalesce(array_length(p_subproject_ids,1),0)>100 then raise exception 'Load at most 100 scoped Subprojects at a time.'; end if;
  for id_value in select distinct unnest(p_subproject_ids) order by 1 loop
    perform public.subproject_accomplishment_actor(p_actor_id,p_actor_password,id_value,p_surface);
    select * into parent from public.subprojects where id=id_value for share;
    perform public.subproject_accomplishment_actor(p_actor_id,p_actor_password,id_value,p_surface);
    result:=result||jsonb_build_array(public.subproject_accomplishment_snapshot(to_jsonb(parent)));
  end loop;
  return result;
end; $$;

create or replace function public.check_subproject_accomplishment_policy(p_actor public.users,p_parent public.subprojects,p_action text,p_month text,p_reason text)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare settings jsonb; overrides jsonb; is_override boolean; allowed boolean; module_name text; v jsonb; rule public.roles_config%rowtype;
begin
  select s.settings into settings from public.dcf_policy_settings s where settings_key='dcf_editing_policy';
  settings:=coalesce(settings,'{}');
  overrides:=coalesce(settings->'monthLock'->'overrideRoles','["Super Admin","Administrator"]');
  is_override:=overrides ? p_actor.role;
  module_name:=case when p_action='editBudget' then 'Subprojects' when p_action='editPhysicalAccomplishment' then 'Accomplishment - Physical' else 'Accomplishment - Financial' end;
  if p_actor.role='Guest' then raise exception 'Guest users cannot change accomplishments.' using errcode='42501'; end if;
  select * into rule from public.roles_config where role=p_actor.role and module=module_name limit 1;
  v:=p_actor.permissions_override->module_name->'can_edit';
  allowed:=case when p_actor.role in ('Super Admin','Administrator') then true when jsonb_typeof(v)='boolean' then (v#>>'{}')::boolean else coalesce(rule.can_edit,false) end;
  if not is_override and not allowed then raise exception 'Accomplishment edit permission is required.' using errcode='42501'; end if;
  v:=settings->'roleRules'->p_actor.role->'subprojects'->p_parent.status->p_action;
  allowed:=case when jsonb_typeof(v)='boolean' then (v#>>'{}')::boolean else p_parent.status=case when p_action='editBudget' then 'Proposed' else 'Ongoing' end or p_actor.role in ('Super Admin','Administrator') end;
  if not is_override and not allowed then raise exception 'Accomplishment editing is locked for this role and status.' using errcode='42501'; end if;
  if is_override and coalesce((settings->'monthLock'->>'requireOverrideReason')::boolean,true) and nullif(btrim(p_reason),'') is null then
    raise exception 'An override reason is required.' using errcode='42501';
  end if;
  -- As in the current UI, an amount-only correction retains its encoded month.
  if p_month is not null and coalesce((settings->'monthLock'->>'enabled')::boolean,true) then
    if p_month !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'A valid accomplishment date is required.'; end if;
    if not is_override and date_trunc('month',p_month::date)<>date_trunc('month',now() at time zone 'Asia/Manila') then
      raise exception 'Only the current accomplishment month is open.' using errcode='42501';
    end if;
  end if;
end; $$;

-- Only explicit changes are merged. In particular, a physical save never sends
-- a cached details array back over another user's financial work.
create or replace function public.patch_subproject_accomplishment(
  p_actor public.users,p_parent public.subprojects,p_base jsonb,p_surface text,p_physical jsonb,p_targets jsonb,p_reason text
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_column
declare
  result jsonb:=to_jsonb(p_parent); original jsonb:=p_base->'subproject'; lines jsonb:=coalesce(p_parent.details,'[]');
  line jsonb; old_line jsonb; values_patch jsonb; addition jsonb; field text; value jsonb; item_id text;
  index_value integer; entry_date text; quantity numeric; active_count integer; complete_count integer; last_date text;
  physical_changed boolean:=false; adjustment_changed boolean; before_value jsonb; current_value jsonb; action_value text;
begin
  if p_surface='financial' and p_physical<>'{}'::jsonb then raise exception 'Financial ACF cannot change physical fields.' using errcode='42501'; end if;
  if p_surface='physical' and (p_physical ? 'additions' or p_physical ? 'adjustments') then raise exception 'Item adjustments require the Subproject editor.' using errcode='42501'; end if;
  if exists(select 1 from jsonb_object_keys(p_physical) k where k not in ('parent','items','additions','commodities')) then raise exception 'Invalid physical change.'; end if;
  if p_physical<>'{}'::jsonb then perform public.check_subproject_accomplishment_policy(p_actor,p_parent,'editPhysicalAccomplishment',null,p_reason); end if;
  for field,value in select * from jsonb_each(coalesce(p_physical->'parent','{}')) loop
    if field not in ('actualMaleBeneficiaries','actualFemaleBeneficiaries','actualFourPsBeneficiaries','actualPWD','actualMuslim','actualLGBTQ','actualSoloParent','actualSenior','actualYouth','accomplishmentRemarks','catchUpPlanRemarks') then raise exception 'Invalid parent accomplishment field.'; end if;
    before_value:=coalesce(nullif(original->field,'null'),'null'); current_value:=coalesce(nullif(result->field,'null'),'null');
    if field not in ('accomplishmentRemarks','catchUpPlanRemarks') then
      if coalesce(before_value,'null')='null' then before_value:='0'; end if;
      if coalesce(current_value,'null')='null' then current_value:='0'; end if;
      if value<>'null' and ((value#>>'{}')::numeric<0 or (value#>>'{}')::numeric<>trunc((value#>>'{}')::numeric) or (value#>>'{}')::numeric::text in ('NaN','Infinity','-Infinity')) then raise exception 'Actual counts must be non-negative whole numbers.'; end if;
    end if;
    if before_value is distinct from current_value then raise exception 'The parent accomplishment changed. Reopen before saving.' using errcode='40001'; end if;
    if field='accomplishmentRemarks' then
      insert into public.budget_item_adjustment_history(source_type,parent_id,item_id,action,before_snapshot,after_snapshot,reason,created_by,created_by_name)
        values('subproject_detail',p_parent.id,p_parent.id::text,'update_accomplishment_remarks',jsonb_build_object('accomplishmentRemarks',result->field),jsonb_build_object('accomplishmentRemarks',value),'Updated subproject accomplishment remarks.',p_actor.username,p_actor."fullName");
    end if;
    result:=result||jsonb_build_object(field,value);
  end loop;
  for addition in select * from jsonb_array_elements(coalesce(p_physical->'additions','[]')) loop
    if p_surface<>'subproject' or p_parent.status='Cancelled' then raise exception 'An item cannot be added from this workflow.' using errcode='42501'; end if;
    if p_parent.status<>'Ongoing' and p_actor.role not in ('Super Admin','Administrator') and not coalesce((select coalesce(settings->'monthLock'->'overrideRoles','["Super Admin","Administrator"]') ? p_actor.role from public.dcf_policy_settings where settings_key='dcf_editing_policy'),false) then raise exception 'Additional physical items require an Ongoing Subproject or a configured override.' using errcode='42501'; end if;
    item_id:=addition->>'id';
    if item_id is null or item_id !~ '^\d+$' or exists(select 1 from jsonb_array_elements(lines) e where e->>'id'=item_id)
      or exists(select 1 from jsonb_array_elements(coalesce(original->'details','[]')) e where e->>'id'=item_id) then raise exception 'An added item requires a fresh identity.'; end if;
    if addition->>'adjustmentType' is null or addition->>'adjustmentType' not in ('Replacement','Additional Item') or addition->>'adjustmentFundingSource' is null or addition->>'adjustmentFundingSource' not in ('Original Allocation','Realignment','Savings') or coalesce((addition->>'isAdjustmentItem')::boolean,false) is not true or nullif(btrim(addition->>'adjustmentReason'),'') is null then raise exception 'An adjustment type, funding source and reason are required.'; end if;
    if exists(select 1 from jsonb_object_keys(addition) k where k not in ('id','budgetItemGroupId','type','particulars','deliveryDate','unitOfMeasure','pricePerUnit','numberOfUnits','objectType','expenseParticular','uacsCode','obligationMonth','disbursementMonth','isAdjustmentItem','adjustmentType','adjustmentFundingSource','replacementOfItemId','sourceItemId','adjustmentReason','replacementReason','itemRemarks','originalPlannedAmount','originalPricePerUnit','originalNumberOfUnits','originalCapturedAt','isSavings','isRealignment')) then raise exception 'Invalid added item field. Actuals must be submitted separately.'; end if;
    if nullif(btrim(addition->>'particulars'),'') is null or nullif(btrim(addition->>'unitOfMeasure'),'') is null or nullif(btrim(addition->>'uacsCode'),'') is null then raise exception 'Added item details are incomplete.'; end if;
    foreach field in array array['pricePerUnit','numberOfUnits'] loop
      quantity:=(addition->>field)::numeric;
      if quantity is null or quantity<=0 or quantity::text in ('NaN','Infinity','-Infinity') then raise exception 'Added item price and quantity must be positive.'; end if;
    end loop;
    if addition->>'adjustmentType'='Replacement' and not exists(select 1 from jsonb_array_elements(lines) e where e->>'id'=coalesce(addition->>'replacementOfItemId',addition->>'sourceItemId') and not coalesce((e->>'isCancelled')::boolean,false)) then raise exception 'The replacement source is unavailable.' using errcode='40001'; end if;
    lines:=lines||jsonb_build_array(addition); physical_changed:=true;
    insert into public.budget_item_adjustment_history(source_type,parent_id,item_id,action,source_item_id,before_snapshot,after_snapshot,amount_delta,reason,created_by,created_by_name)
      values('subproject_detail',p_parent.id,item_id,case when addition->>'adjustmentType'='Replacement' then 'replace_item' else 'create_adjustment_item' end,coalesce(addition->>'sourceItemId',addition->>'replacementOfItemId'),null,addition,(addition->>'pricePerUnit')::numeric*(addition->>'numberOfUnits')::numeric,addition->>'adjustmentReason',p_actor.username,p_actor."fullName");
  end loop;
  for item_id,values_patch in select * from jsonb_each(coalesce(p_physical->'items','{}')) loop
    select value,ordinality::integer-1 into line,index_value from jsonb_array_elements(lines) with ordinality where value->>'id'=item_id;
    select value into old_line from jsonb_array_elements(coalesce(original->'details','[]')) where value->>'id'=item_id;
    if line is null then raise exception 'A physical item was removed or transferred. Reopen before saving.' using errcode='40001'; end if;
    if old_line is null and not exists(select 1 from jsonb_array_elements(coalesce(p_physical->'additions','[]')) e where e->>'id'=item_id) then raise exception 'The physical item is not in the baseline.'; end if;
    if old_line is not null and (coalesce((line->>'isCancelled')::boolean,false) or coalesce((line->>'isSuperseded')::boolean,false)) and exists(select 1 from jsonb_object_keys(values_patch) k where k not in ('isSuperseded','replacedByItemIds','replacementReason')) then raise exception 'The physical item is cancelled or superseded.' using errcode='40001'; end if;
    adjustment_changed:=false;
    for field,value in select * from jsonb_each(values_patch) loop
      if field not in ('actualDeliveryDate','actualNumberOfUnits','isCompleted','isCancelled','isSuperseded','replacedByItemIds','replacementReason','type','particulars','deliveryDate','unitOfMeasure','pricePerUnit','numberOfUnits','objectType','expenseParticular','uacsCode','obligationMonth','disbursementMonth','adjustmentType','adjustmentFundingSource','replacementOfItemId','sourceItemId','adjustmentReason','itemRemarks','isRealignment','isSavings') then raise exception 'Invalid physical item field.'; end if;
      if field not in ('actualDeliveryDate','actualNumberOfUnits','isCompleted') then
        if p_surface<>'subproject' or (field not in ('isSuperseded','replacedByItemIds','replacementReason') and coalesce((line->>'isAdjustmentItem')::boolean,false) is not true) then raise exception 'Original targets cannot be edited through accomplishments.' using errcode='42501'; end if;
        adjustment_changed:=true;
      end if;
      before_value:=coalesce(nullif(old_line->field,'null'),'null'); current_value:=coalesce(nullif(line->field,'null'),'null');
      if old_line is not null and before_value is distinct from current_value then raise exception 'This physical item changed while editing. Reopen before saving.' using errcode='40001'; end if;
      if field='actualDeliveryDate' and nullif(value#>>'{}','') is not null then perform public.check_subproject_accomplishment_policy(p_actor,p_parent,'editPhysicalAccomplishment',value#>>'{}',p_reason); end if;
      if field in ('actualNumberOfUnits','numberOfUnits','pricePerUnit') and value<>'null' and ((value#>>'{}')::numeric<0 or (value#>>'{}')::numeric::text in ('NaN','Infinity','-Infinity')) then raise exception 'Quantities and prices must be non-negative.'; end if;
      line:=line||jsonb_build_object(field,value);
    end loop;
    if adjustment_changed then
      if nullif(btrim(coalesce(line->>'adjustmentReason',line->>'replacementReason',old_line->>'replacementReason',p_reason)),'') is null then raise exception 'An item adjustment reason is required.'; end if;
      action_value:=case when coalesce((line->>'isCancelled')::boolean,false) then 'deactivate_adjustment_item' when old_line->>'adjustmentFundingSource' is distinct from line->>'adjustmentFundingSource' then 'funding_source_changed' else 'edit_adjustment_item' end;
      insert into public.budget_item_adjustment_history(source_type,parent_id,item_id,action,source_item_id,before_snapshot,after_snapshot,amount_delta,reason,created_by,created_by_name)
        values('subproject_detail',p_parent.id,item_id,action_value,line->>'sourceItemId',old_line,line,coalesce((line->>'pricePerUnit')::numeric*(line->>'numberOfUnits')::numeric,0)-coalesce((old_line->>'pricePerUnit')::numeric*(old_line->>'numberOfUnits')::numeric,0),coalesce(line->>'adjustmentReason',line->>'replacementReason',old_line->>'replacementReason',p_reason),p_actor.username,p_actor."fullName");
    end if;
    if values_patch ? 'actualDeliveryDate' or values_patch ? 'actualNumberOfUnits' or values_patch ? 'isCompleted' then
      if nullif(line->>'actualDeliveryDate','') is not null then
        insert into public.subproject_accomplishments(subproject_id,detail_id,delivery_date,quantity,remarks,created_by,created_at)
          values(p_parent.id,item_id::bigint,(line->>'actualDeliveryDate')::date,coalesce((line->>'actualNumberOfUnits')::numeric,0),'Delivered: '||coalesce(line->>'particulars',''),p_actor."fullName",clock_timestamp());
      end if;
    end if;
    lines:=jsonb_set(lines,array[index_value::text],line);
    if exists(select 1 from jsonb_object_keys(values_patch) k where k in ('actualDeliveryDate','actualNumberOfUnits','isCompleted','isCancelled','isSuperseded','replacementOfItemId','sourceItemId')) then physical_changed:=true; end if;
  end loop;
  for addition in select * from jsonb_array_elements(coalesce(p_physical->'commodities','[]')) loop
    index_value:=(addition->>'index')::integer; values_patch:=addition->'values';
    line:=result->'subprojectCommodities'->index_value; old_line:=original->'subprojectCommodities'->index_value;
    if line is null or old_line is null or line->'name' is distinct from old_line->'name' or line->'typeName' is distinct from old_line->'typeName' then raise exception 'Commodity identity changed.' using errcode='40001'; end if;
    for field,value in select * from jsonb_each(values_patch) loop
      if field not in ('actualYield','marketingPercentage','foodSecurityPercentage','income') then raise exception 'Invalid commodity actual field.'; end if;
      if line->field is distinct from old_line->field then raise exception 'Commodity actuals changed.' using errcode='40001'; end if;
      if value<>'null' and ((value#>>'{}')::numeric<0 or (value#>>'{}')::numeric::text in ('NaN','Infinity','-Infinity')) then raise exception 'Invalid commodity actual.'; end if;
      result:=jsonb_set(result,array['subprojectCommodities',index_value::text,field],value);
    end loop;
  end loop;
  for addition in select * from jsonb_array_elements(p_targets) loop
    if p_parent.status<>'Proposed' or p_surface not in ('physical','financial') then raise exception 'Target changes require the existing Proposed budget flow.'; end if;
    perform public.check_subproject_accomplishment_policy(p_actor,p_parent,'editBudget',null,p_reason);
    item_id:=addition->>'itemId'; values_patch:=addition->'values';
    if item_id='$parent' then line:=result; old_line:=original;
    else
      select value,ordinality::integer-1 into line,index_value from jsonb_array_elements(lines) with ordinality where value->>'id'=item_id;
      select value into old_line from jsonb_array_elements(coalesce(original->'details','[]')) where value->>'id'=item_id;
    end if;
    if line is null or old_line is null then raise exception 'Target item changed.' using errcode='40001'; end if;
    for field,value in select * from jsonb_each(values_patch) loop
      if (item_id='$parent' and field<>'estimatedCompletionDate') or (item_id<>'$parent' and field not in ('deliveryDate','numberOfUnits','pricePerUnit','obligationMonth','disbursementMonth')) then raise exception 'Invalid target field.'; end if;
      if coalesce(nullif(line->field,'null'),'null') is distinct from coalesce(nullif(old_line->field,'null'),'null') then raise exception 'Target changed while editing.' using errcode='40001'; end if;
      if field in ('numberOfUnits','pricePerUnit') then
        if value='null' or (value#>>'{}')::numeric<0 or (value#>>'{}')::numeric::text in ('NaN','Infinity','-Infinity') then raise exception 'Invalid target amount or quantity.'; end if;
      elsif nullif(value#>>'{}','') is not null then perform (value#>>'{}')::date; end if;
      line:=line||jsonb_build_object(field,value);
    end loop;
    if item_id='$parent' then result:=line; else lines:=jsonb_set(lines,array[index_value::text],line); end if;
  end loop;
  -- Derive replacement state from live adjustment items, not an arbitrary flag.
  if coalesce(p_physical->'items','{}')<>'{}' or coalesce(p_physical->'additions','[]')<>'[]' then
    for line,index_value in select value,ordinality::integer-1 from jsonb_array_elements(lines) with ordinality loop
      if not coalesce((line->>'isAdjustmentItem')::boolean,false) then
        select coalesce(jsonb_agg(e->'id'),'[]') into addition from jsonb_array_elements(lines) e where e->>'adjustmentType'='Replacement' and not coalesce((e->>'isCancelled')::boolean,false) and coalesce(e->>'replacementOfItemId',e->>'sourceItemId')=line->>'id';
        if jsonb_array_length(addition)>0 or line ? 'replacedByItemIds' then lines:=jsonb_set(lines,array[index_value::text],line||jsonb_build_object('isSuperseded',jsonb_array_length(addition)>0,'replacedByItemIds',addition)); end if;
      end if;
    end loop;
  end if;
  if physical_changed then
    select coalesce(jsonb_agg(case when not coalesce((e->>'isSuperseded')::boolean,false) and (p_parent.status='Proposed' or not coalesce((e->>'isCancelled')::boolean,false)) and nullif(e->>'actualDeliveryDate','') is not null and not(e ? 'isCompleted') then e||'{"isCompleted":true}' else e end order by ordinality),'[]') into lines from jsonb_array_elements(lines) with ordinality as rows(e,ordinality);
    select count(*),count(*) filter(where nullif(e->>'actualDeliveryDate','') is not null and coalesce((e->>'isCompleted')::boolean,false)),max(nullif(e->>'actualDeliveryDate','')) into active_count,complete_count,last_date from jsonb_array_elements(lines) e where not coalesce((e->>'isSuperseded')::boolean,false) and (p_parent.status='Proposed' or not coalesce((e->>'isCancelled')::boolean,false));
    if p_parent.status<>'Cancelled' then result:=result||jsonb_build_object('status',case when active_count>0 and active_count=complete_count then 'Completed' else 'Ongoing' end,'actualCompletionDate',case when active_count>0 and active_count=complete_count then last_date else null end); end if;
    result:=result||jsonb_build_object('physical_accomplishment_submitted_at',case when active_count>0 and active_count=complete_count then clock_timestamp() else null end);
  end if;
  return result||jsonb_build_object('details',case when p_parent.details is null and lines='[]'::jsonb then null else lines end);
end; $$;

create or replace function public.save_subproject_accomplishment(
  p_actor_id bigint,p_actor_password text,p_subproject_id bigint,p_surface text,
  p_base jsonb,p_edits jsonb,p_physical jsonb,p_reason text,p_request_key uuid,p_targets jsonb default '[]'::jsonb
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  actor public.users%rowtype; parent public.subprojects%rowtype; cached public.subproject_accomplishment_requests%rowtype;
  before_parent jsonb; result jsonb; fingerprint text; edit jsonb; op jsonb; baseline jsonb; current_stage jsonb;
  item_id text; stage_value text; table_name text; date_column text; entry jsonb; previous jsonb; intended jsonb; maps jsonb;
  entry_id bigint; new_id bigint; line jsonb; output_lines jsonb; stage_rows jsonb; total numeric; last_date text;
  changed_stages jsonb:='{}'; touched boolean:=false; field text; physical_value jsonb; physical_before jsonb; physical_current jsonb;
  before_changes jsonb:='[]'; after_changes jsonb:='[]'; physical_audit_before jsonb:='{}'; entry_date text; entry_amount numeric; target_edits jsonb:='{}'; target_base jsonb;
  confirmed_financial jsonb:='[]'; ledger_rows jsonb;
begin
  actor:=public.subproject_accomplishment_actor(p_actor_id,p_actor_password,p_subproject_id,p_surface);
  if p_request_key is null or jsonb_typeof(p_edits) is distinct from 'array' or jsonb_typeof(p_physical) is distinct from 'object' or jsonb_typeof(p_base) is distinct from 'object' or jsonb_typeof(p_targets) is distinct from 'array' then raise exception 'An explicit accomplishment draft and request key are required.'; end if;
  fingerprint:=md5(jsonb_build_object('base',p_base,'edits',p_edits,'physical',p_physical,'reason',p_reason,'surface',p_surface,'targets',p_targets)::text);
  select * into parent from public.subprojects where id=p_subproject_id for update;
  actor:=public.subproject_accomplishment_actor(p_actor_id,p_actor_password,p_subproject_id,p_surface);
  select * into cached from public.subproject_accomplishment_requests where request_key=p_request_key;
  if cached.request_key is not null then
    if cached.subproject_id<>p_subproject_id or cached.actor_id<>actor.id or cached.request_hash<>fingerprint then raise exception 'This request key belongs to a different draft.'; end if;
    return cached.response;
  end if;
  before_parent:=to_jsonb(parent);
  if (p_base->'subproject'->>'id')::bigint is distinct from parent.id then raise exception 'The accomplishment baseline does not belong to this Subproject.'; end if;
  foreach field in array array['status','workflow_status','operatingUnit','budgetItemTransferId'] loop
    if before_parent->field is distinct from p_base->'subproject'->field then raise exception 'The Subproject identity or workflow changed. Reopen before saving.' using errcode='40001'; end if;
  end loop;
  if parent."budgetItemTransferId" is not null and parent.workflow_status is distinct from 'APPROVED' then raise exception 'This transfer is not approved.' using errcode='42501'; end if;
  if exists(select 1 from jsonb_array_elements(p_edits) e group by e->>'itemId',e->>'stage' having count(*)>1) then raise exception 'Duplicate financial stages in this request.'; end if;
  before_parent:=public.patch_subproject_accomplishment(actor,parent,p_base,p_surface,p_physical,p_targets,p_reason);
  if before_parent is distinct from to_jsonb(parent) then touched:=true; end if;
  for edit in select value from jsonb_array_elements(p_edits) loop
    item_id:=edit->>'itemId'; stage_value:=edit->>'stage';
    if stage_value is null or stage_value not in ('obligation','disbursement') or jsonb_typeof(edit->'operations') is distinct from 'array' then raise exception 'Invalid financial change.'; end if;
    if jsonb_array_length(edit->'operations')=0 then continue; end if;
    perform public.check_subproject_accomplishment_policy(actor,parent,'editFinancialAccomplishment',null,p_reason);
    if p_surface='physical' then raise exception 'Physical ACF cannot change financial entries.' using errcode='42501'; end if;
    select value into line from jsonb_array_elements(coalesce(nullif(before_parent->'details','null'::jsonb),'[]'::jsonb)) where value->>'id'=item_id;
    if line is null or coalesce((line->>'isCancelled')::boolean,false) or coalesce((line->>'isSuperseded')::boolean,false) then raise exception 'The budget item was removed, cancelled or superseded.' using errcode='40001'; end if;
    if line->>'fundingOrigin'='SupplementalDraft' or (nullif(line->>'supplementUid','') is not null and line->>'supplementStatus' is distinct from 'APPROVED') then raise exception 'The supplemental budget item is not approved.' using errcode='42501'; end if;
    baseline:=p_base->'stages'->item_id->stage_value;
    if baseline is null and exists(select 1 from jsonb_array_elements(coalesce(p_physical->'additions','[]')) e where e->>'id'=item_id) then baseline:='{"source":"legacy","entries":[]}'; end if;
    current_stage:=public.subproject_financial_stage(before_parent,item_id,stage_value);
    if baseline is null or baseline->>'source' is distinct from current_stage->>'source' then raise exception 'Financial entry storage changed. Reopen before saving.' using errcode='40001'; end if;
    table_name:=case when stage_value='obligation' then 'financial_obligations' else 'financial_disbursements' end;
    date_column:=case when stage_value='obligation' then 'obligation_date' else 'disbursement_date' end;
    maps:='{}';
    if baseline->>'source'='legacy' then
      if baseline is distinct from current_stage then raise exception 'The legacy actuals changed. Reopen before saving.' using errcode='40001'; end if;
      -- Materialize every original legacy entry once, preserving duplicates/amounts.
      for entry in select value from jsonb_array_elements(baseline->'entries') loop
        entry_date:=nullif(entry->>'date','');
        if entry_date is null then
          select nullif(value->'value'->>'date','') into entry_date from jsonb_array_elements(edit->'operations')
            where value->>'action'='update' and value->>'id'=entry->>'id';
        end if;
        if entry_date is null then raise exception 'A legacy entry needs its actual date before this stage can be saved.'; end if;
        execute format('insert into public.%I(entity_type,parent_id,item_id,%I,amount,remarks) values(''subproject_detail'',$1,$2,$3::date,$4,$5) returning id',table_name,date_column)
          into new_id using parent.id,item_id,entry_date,(entry->>'amount')::numeric,entry->>'remarks';
        maps:=maps||jsonb_build_object(entry->>'id',new_id);
      end loop;
    end if;
    if exists(select 1 from jsonb_array_elements(edit->'operations') o group by o->>'id' having count(*)>1) then raise exception 'Duplicate entry operations.'; end if;
    for op in select value from jsonb_array_elements(edit->'operations') loop
      if op->>'action' is null or op->>'action' not in ('insert','update','delete') then raise exception 'Unknown financial operation.'; end if;
      previous:=null;
      select value into previous from jsonb_array_elements(baseline->'entries') where value->>'id'=op->>'id';
      if op->>'action'='insert' then
        if previous is not null or nullif(op->>'id','') is null then raise exception 'New entries require a fresh local identity.'; end if;
      else
        if previous is null then raise exception 'The edited financial entry is not in the baseline.'; end if;
        if baseline->>'source'='central' then
          select value into entry from jsonb_array_elements(current_stage->'entries') where value->>'id'=op->>'id';
          if entry is distinct from previous then raise exception 'This financial entry changed or was removed while editing. Your draft was not saved.' using errcode='40001'; end if;
          entry_id:=(previous->>'id')::bigint;
        else entry_id:=(maps->>(previous->>'id'))::bigint; end if;
      end if;
      if op->>'action'='delete' then
        if coalesce((op->>'explicit')::boolean,false) is not true then raise exception 'An explicit removal action is required. Missing entries are never deleted automatically.'; end if;
        execute format('delete from public.%I where id=$1 and entity_type=''subproject_detail'' and parent_id=$2 and item_id::text=$3',table_name) using entry_id,parent.id,item_id;
      else
        intended:=op->'value'; entry_date:=nullif(intended->>'date',''); entry_amount:=(intended->>'amount')::numeric;
        if entry_date is null or entry_amount is null or entry_amount=0 or entry_amount::text in ('NaN','Infinity','-Infinity') or (stage_value='disbursement' and entry_amount<0) then raise exception 'Every entry requires a valid date and amount.'; end if;
        if stage_value='obligation' and entry_amount<0 and nullif(btrim(intended->>'remarks'),'') is null then raise exception 'A reason is required for negative obligations.'; end if;
        if previous is null or left(coalesce(previous->>'date',''),7)<>left(entry_date,7) then perform public.check_subproject_accomplishment_policy(actor,parent,'editFinancialAccomplishment',entry_date,p_reason); end if;
        if op->>'action'='insert' then
          execute format('insert into public.%I(entity_type,parent_id,item_id,%I,amount,remarks) values(''subproject_detail'',$1,$2,$3::date,$4,$5) returning id',table_name,date_column)
            into new_id using parent.id,item_id,entry_date,entry_amount,coalesce(intended->>'remarks','');
        else
          execute format('update public.%I set %I=$1::date,amount=$2,remarks=$3 where id=$4 and entity_type=''subproject_detail'' and parent_id=$5 and item_id::text=$6',table_name,date_column)
            using entry_date,entry_amount,coalesce(intended->>'remarks',''),entry_id,parent.id,item_id;
        end if;
      end if;
    end loop;
    insert into public.subproject_financial_entry_state values(parent.id,item_id,stage_value) on conflict do nothing;
    changed_stages:=changed_stages||jsonb_build_object(item_id||':'||stage_value,jsonb_build_object('itemId',item_id,'stage',stage_value));
    before_changes:=before_changes||jsonb_build_array(jsonb_build_object('itemId',item_id,'stage',stage_value,'before',current_stage));
    touched:=true;
  end loop;
  output_lines:='[]';
  for line in select value from jsonb_array_elements(coalesce(nullif(before_parent->'details','null'::jsonb),'[]'::jsonb)) loop
    item_id:=line->>'id';
    foreach stage_value in array array['obligation','disbursement'] loop
      if not(changed_stages ? (item_id||':'||stage_value)) then continue; end if;
      current_stage:=public.subproject_financial_stage(to_jsonb(parent),item_id,stage_value); stage_rows:=current_stage->'entries';
      select coalesce(sum((v->>'amount')::numeric),0),max(nullif(v->>'date','')) into total,last_date from jsonb_array_elements(stage_rows) v;
      if stage_value='obligation' then
        line:=line||jsonb_build_object('obligations',stage_rows,'actualObligationAmount',total,'actualObligationDate',last_date);
        if line ? 'actualAmount' then line:=line||jsonb_build_object('actualAmount',total); end if;
      else line:=line||jsonb_build_object('disbursements',stage_rows,'actualDisbursementAmount',total,'actualDisbursementDate',last_date); end if;
      after_changes:=after_changes||jsonb_build_array(jsonb_build_object('itemId',item_id,'stage',stage_value,'after',current_stage));
      table_name:=case when stage_value='obligation' then 'financial_obligations' else 'financial_disbursements' end;
      execute format('select coalesce(jsonb_agg(to_jsonb(r) order by id),''[]''::jsonb) from public.%I r where entity_type=''subproject_detail'' and parent_id=$1 and item_id::text=$2',table_name) into ledger_rows using parent.id,item_id;
      confirmed_financial:=confirmed_financial||jsonb_build_array(jsonb_build_object('itemId',item_id,'stage',stage_value,'rows',ledger_rows));
    end loop;
    output_lines:=output_lines||jsonb_build_array(line);
  end loop;
  if touched then
    parent:=jsonb_populate_record(parent,before_parent||jsonb_build_object('details',case when changed_stages<>'{}'::jsonb then output_lines else before_parent->'details' end));
    update public.subprojects set details=parent.details,
      "actualMaleBeneficiaries"=parent."actualMaleBeneficiaries","actualFemaleBeneficiaries"=parent."actualFemaleBeneficiaries","actualFourPsBeneficiaries"=parent."actualFourPsBeneficiaries",
      "actualPWD"=parent."actualPWD","actualMuslim"=parent."actualMuslim","actualLGBTQ"=parent."actualLGBTQ","actualSoloParent"=parent."actualSoloParent","actualSenior"=parent."actualSenior","actualYouth"=parent."actualYouth",
      "subprojectCommodities"=parent."subprojectCommodities","accomplishmentRemarks"=parent."accomplishmentRemarks","catchUpPlanRemarks"=parent."catchUpPlanRemarks",
      "estimatedCompletionDate"=parent."estimatedCompletionDate","actualCompletionDate"=parent."actualCompletionDate",
      status=parent.status,physical_accomplishment_submitted_at=parent.physical_accomplishment_submitted_at,
      history=coalesce(parent.history,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('date',clock_timestamp(),'event','Updated accomplishment','user',actor."fullName")),updated_at=clock_timestamp()
      where id=parent.id returning * into parent;
    insert into public.subproject_accomplishment_revisions(subproject_id,actor_id,request_key,reason,changes)
      values(parent.id,actor.id,p_request_key,nullif(btrim(p_reason),''),jsonb_build_object('before',before_changes,'after',after_changes,'physicalBefore',physical_audit_before,'physicalChanges',p_physical,'targetChanges',p_targets));
  end if;
  result:=public.subproject_accomplishment_snapshot(to_jsonb(parent))||jsonb_build_object('confirmedFinancial',confirmed_financial);
  insert into public.subproject_accomplishment_requests values(p_request_key,parent.id,actor.id,fingerprint,result,now());
  return result;
end; $$;

revoke all on function public.subproject_accomplishment_actor(bigint,text,bigint,text),public.subproject_financial_stage(jsonb,text,text),public.subproject_accomplishment_snapshot(jsonb),public.check_subproject_accomplishment_policy(public.users,public.subprojects,text,text,text),public.patch_subproject_accomplishment(public.users,public.subprojects,jsonb,text,jsonb,jsonb,text) from public,anon,authenticated;
revoke all on function public.read_subproject_accomplishments(bigint,text,bigint[],text),public.save_subproject_accomplishment(bigint,text,bigint,text,jsonb,jsonb,jsonb,text,uuid,jsonb) from public;
grant execute on function public.read_subproject_accomplishments(bigint,text,bigint[],text),public.save_subproject_accomplishment(bigint,text,bigint,text,jsonb,jsonb,jsonb,text,uuid,jsonb) to anon,authenticated;
do $$
declare fingerprints jsonb;
begin
  select jsonb_object_agg(table_name,signature) into fingerprints from (
    select 'subprojects' as table_name,jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) as signature from public.subprojects r
    union all select 'financial_obligations',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.financial_obligations r
    union all select 'financial_disbursements',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.financial_disbursements r
    union all select 'subproject_accomplishments',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.subproject_accomplishments r
    union all select 'budget_item_adjustment_history',jsonb_build_object('count',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' order by id),''))) from public.budget_item_adjustment_history r
  ) signatures;
  if fingerprints is distinct from current_setting('app.subproject_actuals_install_fingerprints')::jsonb then
    raise exception 'Existing Subproject or financial records changed during installation. Migration rolled back.';
  end if;
end; $$;
commit;
